package com.qtekfun.ultimatealarm.feature.sounds

import androidx.annotation.StringRes

/** RF-S1 categories. */
enum class SoundCategory(@StringRes val label: Int) {
    GENTLE(R.string.category_gentle),
    ENERGETIC(R.string.category_energetic),
    BACKUP(R.string.category_backup),
    NOTIFICATION(R.string.category_notification)
}

data class BundledSound(val id: String, val category: SoundCategory, @StringRes val name: Int) {
    val assetPath: String get() = "sounds/$id.ogg"
}

/** The pack in `assets/sounds` (generated by tools/sounds, licences in LICENSES.md). */
object SoundCatalog {
    val all = listOf(
        BundledSound("dawn_marimba", SoundCategory.GENTLE, R.string.sound_dawn_marimba),
        BundledSound("morning_bells", SoundCategory.GENTLE, R.string.sound_morning_bells),
        BundledSound("soft_pad", SoundCategory.GENTLE, R.string.sound_soft_pad),
        BundledSound("music_box", SoundCategory.GENTLE, R.string.sound_music_box),
        BundledSound("gentle_chimes", SoundCategory.GENTLE, R.string.sound_gentle_chimes),
        BundledSound("bright_marimba", SoundCategory.ENERGETIC, R.string.sound_bright_marimba),
        BundledSound("sunrise_arpeggio", SoundCategory.ENERGETIC, R.string.sound_sunrise_arpeggio),
        BundledSound("wake_pluck", SoundCategory.ENERGETIC, R.string.sound_wake_pluck),
        BundledSound("rise_bells", SoundCategory.ENERGETIC, R.string.sound_rise_bells),
        BundledSound("backup_pulse", SoundCategory.BACKUP, R.string.sound_backup_pulse),
        BundledSound("backup_two_tone", SoundCategory.BACKUP, R.string.sound_backup_two_tone),
        BundledSound("eve_chime", SoundCategory.NOTIFICATION, R.string.sound_eve_chime),
        BundledSound("timer_done", SoundCategory.NOTIFICATION, R.string.sound_timer_done)
    )

    /** Default wake-up tone: the first link of the fallback chain (§5.3). */
    val DEFAULT_ALARM = SoundRef.Bundled("dawn_marimba")

    /** Default backup tone (RF-S5). */
    val DEFAULT_BACKUP = SoundRef.Bundled("backup_pulse")

    fun byId(id: String): BundledSound? = all.firstOrNull { it.id == id }

    fun alarmChoices(): List<BundledSound> = all.filter { it.category == SoundCategory.GENTLE || it.category == SoundCategory.ENERGETIC }

    fun backupChoices(): List<BundledSound> = all.filter { it.category == SoundCategory.BACKUP }

    /**
     * The order in which sources are tried when ringing (§5.3): the chosen sound, the pack default for that use, then the
     * system alarm tone; the player adds a generated beep at the end. Duplicates removed.
     */
    fun chain(chosen: SoundRef?, backup: Boolean): List<SoundRef> {
        val default = if (backup) DEFAULT_BACKUP else DEFAULT_ALARM
        return listOfNotNull(chosen, default, SoundRef.System(SYSTEM_DEFAULT)).distinct()
    }

    /** Marker for "the system's default alarm tone", resolved by the player. */
    const val SYSTEM_DEFAULT = "default"
}
